$users = @( @{user="shekai"; pass="BlueShekai2026!"}, @{user="staff1"; pass="BlueStaff1!"}, @{user="staff2"; pass="BlueStaff2!"} ); foreach ($u in $users) { Write-Host "Testing user: $($u.user)"; try { $loginBody = @{ username = $u.user; password = $u.pass } | ConvertTo-Json; $loginRes = Invoke-RestMethod -Uri \"http://localhost:3000/api/login\" -Method Post -Body $loginBody -ContentType \"application/json\" -WebSession $session; Write-Host \"Login successful: $($u.user)\"; try { $adminRes = Invoke-WebRequest -Uri \"http://localhost:3000/admin-monitoring\" -WebSession $session -ErrorAction Stop; Write-Host \"$($u.user) access to /admin-monitoring: $($adminRes.StatusCode)\" } catch { if ($_.Exception.Response) { Write-Host \"$($u.user) access to /admin-monitoring: $($_.Exception.Response.StatusCode.value__)\" } else { Write-Host \"$($u.user) access to /admin-monitoring: error status\" } } } catch { Write-Host \"Login failed for $($u.user): $($_.Exception.Message)\" }; Write-Host \"----------------\" }
